        return self.role == "ai"

    @property
    def is_observation(self) -> bool:
        return self.role == "user" and self.index > 0

    @property
    def is_system(self) -> bool:
        return self.role == "system"

    @property
    def command(self) -> Optional[str]:
        if self.role != "ai":
